```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Click the Target</title>
</head>
<body>
    <div id="canvas">
        <canvas width="600" height="400"></canvas>
    </div>
    <button id="startBtn">Start Game</button>
    <p id="score">Score: <span id="currentScore">0</span></p>
    <div id="timer">Time Left: <span id="timeLeft">30</span></spacer> </div>
    <div id="gameOver" style="display: none;">
        <h1>Game Over! Final Score: <span id="finalScore">0</span></h1>
    </div>

    <script>
        const canvas = document.getElementById("canvas");
        const ctx = canvas.getContext("2d");
        const startBtn = document.getElementById("startBtn");
        const scoreElement = document.getElementById("score");
        const currentScoreElement = document.getElementById("currentScore");
        const timeLeftElement = document.getElementById("timeLeft");
        const gameOverElement = document.getElementById("gameOver");

        let targetX;
        let targetY;
        let score = 0;
        let timeLeft = 30 * 60; // 30 seconds in milliseconds
        let finalScore = 0;

        function init() {
            canvas.width = 600;
            canvas.height = 400;
            document.body.appendChild(canvas);

            targetX = Math.floor(Math.random() * canvas.width);
            targetY = Math.floor(Math.random() * canvas.height);
            scoreElement.textContent = score;
            currentScoreElement.textContent = "Current Score: ";
            timeLeftElement.textContent = timeLeft;

            gameOverElement.style.display = "none";
            startBtn.addEventListener("click", startGame);
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = "blue";
            ctx.beginPath();
            ctx.arc(targetX, targetY, 50, 0, 2 * Math.PI);
            ctx.fill();

            ctx.font = "24px Arial";
            ctx.fillStyle = "white";
            ctx.textAlign = "center";
            ctx.fillText("Score: " + score + "/" + finalScore + " | Time Left: " + timeLeft, canvas.width / 2, canvas.height - 50);

            if (score >= 30) {
                finalScore = score;
                gameOverElement.style.display = "block";
                timeLeft -= 60;
            }

            requestAnimationFrame(draw);
        }

        function startGame() {
            document.body.removeChild(canvas);
            init();
        }

        init();
    </script>
</body>
</html>
```
This code creates a simple click-the-target game with a 30-second timer and displays the final score after the game is over. The start button will restart the game if clicked again within the current session.
